 pause(){this.suspendedPlaying=false;this.playing=false;this.resumeAfterSeek=false;this.started=false;this.playToken++;this.buffering.clear();this.videos.forEach(video=>video.pause());const ended=this.replayOnEnd&&this.master?.currentTime>=this.duration-.03;this.playButton.innerHTML=uiIcon('Play')+this.label(ended?'重播':'播放',ended?'Replay':'Play');cancelAnimationFrame(this.frame);}
 buffer(video){if(!this.playing||!this.started||video.seeking)return;this.buffering.add(video);this.videos.filter(item=>item!==video).forEach(item=>item.pause());this.root.querySelector('[data-session-state]').textContent=this.label('等待缓冲，保持同步','Buffering while keeping both videos synchronized');}
