function showcaseTitle(item){const shot=byId.get(normId(item.shot));return t(item.name||zh(shot),shot?en(shot):item.name);}
function showcaseCaption(item,key){return t(item[key]||'',showcaseEnglish[item[key]]||(key==='theme_zh'?'Finished shot':'Shot description'));}
function showcaseOriginalMarkup(item,key){if(window.Shell.lang!=='en'||!item[key]||showcaseEnglish[item[key]])return '';return '<p class="showcase-original" lang="zh-CN"><span lang="en">'+(key==='theme_zh'?'Original theme: ':'Original description: ')+'</span>'+esc(item[key])+'</p>';}
function showcaseDescriptionMarkup(item){if(!item.meaning_zh)return '';return window.Shell.lang==='en'&&!showcaseEnglish[item.meaning_zh]?showcaseOriginalMarkup(item,'meaning_zh'):'<p class="showcase-context">'+esc(showcaseCaption(item,'meaning_zh'))+'</p>';}
function communityMarkup(subject){const follow=window.SITE_CONFIG?.follow||{},feedback=window.Shell?.feedbackUrl?.(subject)||'';if(!follow.x&&!follow.site&&!feedback)return '';return '<div class="community-card" data-community>'+((follow.x||follow.site)?'<section><h2>'+t('关注更新','Follow updates')+'</h2><p>'+t('新的运镜条目、成片对照和导演台功能会先发在 X 上。','New entries, film comparisons and director features are posted on X first.')+'</p><div class="actions">'+(follow.x?'<a class="btn primary" data-site-follow="x" href="'+esc(follow.x)+'" target="_blank" rel="noopener"><span aria-hidden="true">𝕏</span>'+t('在 X 上关注','Follow on X')+'</a>':'')+(follow.site?'<a class="btn ghost" data-site-follow="site" href="'+esc(follow.site)+'" target="_blank" rel="noopener">'+t('作者官网','Author site')+uiIcon('MoveUpRight')+'</a>':'')+'</div></section>':'')+(feedback?'<section><h2>'+t('提建议 / 报问题','Suggest or report')+'</h2><p>'+t('提示词不准、画面不对、哪里不好用，都欢迎在 GitHub 提一个 issue，页面地址会自动带上。','Wrong prompt, broken frame or awkward UI — open a GitHub issue; this page link is filled in for you.')+'</p><div class="actions"><a class="btn primary" data-feedback href="'+esc(feedback)+'" target="_blank" rel="noopener">'+uiIcon('MessageSquareText')+t('去 GitHub 反馈','Give feedback on GitHub')+'</a></div></section>':'')+'</div>';}
function followMarkup(){const config=window.SITE_CONFIG?.follow||{},links=[['x',t('在 X 上关注更新','Follow updates on X')],['site',t('访问作者官网','Visit the author’s website')]].filter(([key])=>config[key]);if(!links.length)return '';return '<footer class="site-follow" data-showcase-section="follow"><p>'+t('继续发现镜头语言','Keep exploring camera language')+'</p><div>'+links.map(([key,label])=>'<a class="text-button" data-site-follow="'+key+'" href="'+esc(config[key])+'" target="_blank" rel="noopener">'+esc(label)+uiIcon('MoveUpRight')+'</a>').join('')+'</div></footer>';}
function showcaseCard(item){return '<a class="showcase-card" data-showcase-item="'+esc(item.id)+'" href="'+esc(dictionaryUrl(item.shot,item.id))+'">'+imageMarkup(publicAsset(item.poster),showcaseTitle(item))+'<span class="showcase-card-copy"><small>#'+esc(item.shot)+'</small><strong>'+esc(showcaseTitle(item))+'</strong><span>'+esc(showcaseCaption(item,'theme_zh'))+'</span>'+showcaseOriginalMarkup(item,'theme_zh')+'</span></a>';}
