 SCENE_NAMES={S1:['广场','Plaza'],S2:['室内','Interior'],S3:['门厅走廊','Hall & corridor'],S4:['街道','Street'],S5:['剧场','Theatre'],S6:['海岸峡谷','Coastal canyon']};
