class LandingController{
 constructor(root){
  this.root=root;this.abort=new AbortController();this.timers=new Set();this.frames=new Set();this.hoverStops=[];this.reel=window.SHOWCASE_META?.hero_reel;this.video=root.querySelector('[data-reel-video]');this.selected=-1;this.wanted=!reducedMotion.matches;
  const signal=this.abort.signal;this.listen=(node,type,fn)=>node?.addEventListener(type,fn,{signal});
  this.search();this.reveal();this.dimensions();this.director();this.reelPlayer();
  this.listen(root,'pointermove',e=>{if(reducedMotion.matches||coarsePointer.matches)return;const card=e.target.closest('[data-landing-door]');if(card){const r=card.getBoundingClientRect();card.style.setProperty('--spot-x',e.clientX-r.left+'px');card.style.setProperty('--spot-y',e.clientY-r.top+'px');}const player=e.target.closest('.landing-player');if(player){const r=player.getBoundingClientRect();player.style.setProperty('--tilt-y',((e.clientX-r.left)/r.width-.5)*10+'deg');player.style.setProperty('--tilt-x',(.5-(e.clientY-r.top)/r.height)*10+'deg');}});
  this.listen(root.querySelector('.landing-player'),'pointerleave',()=>{root.querySelector('.landing-player')?.style.setProperty('--tilt-x','0deg');root.querySelector('.landing-player')?.style.setProperty('--tilt-y','0deg');});
  this.listen(document,'visibilitychange',()=>{if(document.hidden){this.stopHover();this.video?.pause();}else if(this.wanted)this.play();});
  this.listen(reducedMotion,'change',()=>{if(reducedMotion.matches){this.wanted=false;this.video?.pause();this.stopHover();this.observer?.disconnect();root.querySelectorAll('[data-landing-door]').forEach(e=>e.classList.add('revealed'));root.querySelectorAll('[data-count]').forEach(e=>e.textContent=e.dataset.count);}});
 }
 later(fn,delay){const timer=setTimeout(()=>{this.timers.delete(timer);if(!this.abort.signal.aborted)fn();},delay);this.timers.add(timer);return timer;}
 stopHover(){this.hoverStops.forEach(fn=>fn());}
 search(){
  const input=this.root.querySelector('#landing-search'),list=this.root.querySelector('#landing-results');let results=[],index=0;
  const select=next=>{index=Math.max(0,Math.min(results.length-1,next));list.querySelectorAll('[data-result]').forEach((a,i)=>{const active=i===index;a.classList.toggle('active',active);a.setAttribute('aria-selected',String(active));});if(results.length)input.setAttribute('aria-activedescendant','landing-result-'+idOf(results[index]));};
  const close=()=>{list.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');};
  const render=()=>{const query=input.value.trim();if(!query){close();return;}results=searchShots(query).slice(0,6);index=0;list.innerHTML=results.length?results.map((shot,i)=>'<a id="landing-result-'+idOf(shot)+'" data-result="'+i+'" data-search-id="'+idOf(shot)+'" href="'+esc(dictionaryUrl(idOf(shot)))+'" role="option" aria-selected="false"><img src="'+esc(publicAsset(shot.media?.poster))+'" alt="" decoding="async"><span><strong>'+highlight(t(zh(shot),en(shot)),query)+'</strong><small>'+highlight(t(en(shot),zh(shot)),query)+'</small>'+searchSnippet(shot,query)+'</span><code>'+idOf(shot)+'</code></a>').join(''):'<p class="landing-empty">'+t('没有找到镜头，试试换个说法。','No shots found. Try another name or effect.')+'</p>';list.hidden=false;input.setAttribute('aria-expanded','true');select(0);};
  this.listen(input,'input',render);this.listen(input,'focus',()=>{if(input.value)render();});
  this.listen(input,'keydown',e=>{if(e.key==='Escape'){e.preventDefault();close();return;}if(!results.length||list.hidden)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();select(index+(e.key==='ArrowDown'?1:-1));}else if(e.key==='Enter'){e.preventDefault();location.assign(dictionaryUrl(idOf(results[index])));}});
  this.listen(list,'pointermove',e=>{const a=e.target.closest('[data-result]');if(a)select(Number(a.dataset.result));});
  this.listen(document,'pointerdown',e=>{if(!e.target.closest('.landing-search'))close();});
  this.listen(this.root.querySelector('.landing-search'),'focusout',e=>{if(!e.currentTarget.contains(e.relatedTarget))close();});
  this.listen(document,'keydown',e=>{if(e.key==='/'&&!e.target.matches('input,textarea,select,[contenteditable]')){e.preventDefault();e.stopImmediatePropagation();input.focus();}});
 }
 reveal(){
  const reveal=card=>{card.classList.add('revealed');card.querySelectorAll('[data-count]').forEach(node=>{if(reducedMotion.matches)return;const total=Number(node.dataset.count),start=performance.now();const frame=now=>{const u=Math.min(1,(now-start)/280);node.textContent=String(Math.round(total*(1-(1-u)**3)));if(u<1&&!this.abort.signal.aborted){const id=requestAnimationFrame(t=>{this.frames.delete(id);frame(t);});this.frames.add(id);}};frame(start);});};
  if(reducedMotion.matches||!('IntersectionObserver'in window)){this.root.querySelectorAll('[data-landing-door]').forEach(reveal);return;}
  this.observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){reveal(entry.target);this.observer.unobserve(entry.target);}}),{threshold:.08});this.root.querySelectorAll('[data-landing-door]').forEach(e=>this.observer.observe(e));
 }
 dimensions(){
  this.root.querySelectorAll('[data-dimension]').forEach(card=>{
   const d=landingDimensions.find(d=>d.key===card.dataset.dimension),image=card.querySelector('img'),label=card.querySelector('[data-dimension-label]'),video=card.querySelector('video');let timer=null,index=0,active=false;
   const show=id=>{const shot=byId.get(id);image.src=publicAsset(shot.media.poster);card.dataset.previewShot=id;label.textContent=t(zh(shot),en(shot));};
   const stop=()=>{active=false;if(timer){clearTimeout(timer);this.timers.delete(timer);timer=null;}video?.pause();if(video){video.removeAttribute('src');video.load();}card.classList.remove('previewing');show(d.ids[0]);};this.hoverStops.push(stop);
   const start=()=>{if(active||reducedMotion.matches||document.hidden)return;active=true;card.classList.add('previewing');if(video){show('041');video.src=publicAsset(byId.get('041').media.video);video.play().catch(()=>{});}else{index=0;const advance=()=>{if(!active)return;index=(index+1)%d.ids.length;show(d.ids[index]);timer=this.later(advance,1400);};timer=this.later(advance,1400);}};
   this.listen(card,'pointerenter',()=>{if(!coarsePointer.matches)start();});this.listen(card,'pointerleave',()=>{if(document.activeElement!==card)stop();});this.listen(card,'focus',start);this.listen(card,'blur',stop);show(d.ids[0]);
  });
 }
 director(){
  const card=this.root.querySelector('.director-door'),pane=card.querySelector('[data-director-comparison]'),ref=card.querySelector('[data-director-ref]'),out=card.querySelector('[data-director-out]'),demo=card.querySelector('[data-director-demo]');
  const item=showcaseItems.find(i=>i.id==='057_v01')||this.reel?.comparison||showcaseItems[0]||window.SHOWCASE_META?.director?.reference;let active=false;card.querySelector('[data-director-out-pane]').hidden=!item?.out;if(item&&!item.out)pane.querySelector('p').textContent=t('导演台导出','Director export');
  const control=document.createElement('button');control.className='btn director-compare-play';control.textContent=t('播放对照','Play comparison');control.dataset.directorComparePlay='';pane.append(control);
  const stop=()=>{active=false;ref.pause();out.pause();demo.pause();control.textContent=t('播放对照','Play comparison');};this.hoverStops.push(stop);
  const start=(manual=false)=>{if(active||!manual&&reducedMotion.matches||document.hidden)return;active=true;control.textContent=t('暂停对照','Pause comparison');demo.pause();if(!item){pane.hidden=true;return;}pane.hidden=false;for(const [v,key]of[[ref,'ref'],[out,'out']])if(item[key]&&!v.getAttribute('src')){v.src=publicAsset(item[key]);v.load();}card.querySelector('[data-director-out-pane]').hidden=!item.out;ref.currentTime=0;if(item.out)out.currentTime=0;ref.play().catch(()=>{});if(item.out)out.play().catch(()=>{});};
  // Synchronize from native time updates only while the comparison is hovered.
  this.listen(ref,'timeupdate',()=>{if(active&&!out.paused&&!out.seeking&&Math.abs(ref.currentTime-out.currentTime)>.10)out.currentTime=Math.min(ref.currentTime,out.duration||ref.currentTime);});
  this.listen(card,'pointerenter',()=>{if(!coarsePointer.matches)start();});this.listen(card,'pointerleave',()=>{if(!coarsePointer.matches)stop();});this.listen(card,'focusin',e=>{if(!e.target.matches('[data-director-demo-play],[data-director-compare-play]'))start();});this.listen(card,'focusout',e=>{if(!card.contains(e.relatedTarget))stop();});
  if(coarsePointer.matches){pane.classList.add('touch-visible');if(item){const shot=item.shot||item.id?.slice(0,3);ref.poster=publicAsset(item.ref_poster||this.reel?.segments?.find(s=>s.shot===shot&&s.kind==='blockout')?.poster||item.poster||this.reel?.poster);out.poster=publicAsset(item.poster||this.reel?.poster);}else pane.hidden=true;}
  this.listen(control,'click',()=>active?stop():start(true));
  this.listen(card.querySelector('[data-director-demo-play]'),'click',()=>{if(!demo.paused){demo.pause();return;}stop();card.classList.add('demo-active');demo.src=publicAsset('showcase/director_demo.mp4');demo.play().catch(()=>{});});
 }
 reelPlayer(){
  if(!this.video)return;const video=this.video,segments=this.reel?.segments||[],button=this.root.querySelector('[data-reel-play]'),strip=this.root.querySelector('.reel-strip');
  const memory=heroPlayback.get('t7-reel');if(memory){this.wanted=memory.wanted&&!reducedMotion.matches;this.listen(video,'loadedmetadata',()=>{if(memory.time<video.duration)video.currentTime=memory.time;});}
  if(segments.length){const track=video.addTextTrack('metadata');track.mode='hidden';segments.forEach((s,i)=>{const cue=new VTTCue(s.start,s.end,String(i));track.addCue(cue);});this.listen(track,'cuechange',()=>{const cue=track.activeCues?.[0];if(cue)this.segment(false,Number(cue.text));});}
  this.listen(button,'click',()=>{this.wanted=!this.wanted;if(this.wanted)this.play();else video.pause();});
  this.root.querySelectorAll('[data-reel-seek]').forEach(el=>this.listen(el,'click',()=>{video.currentTime=segments[Number(el.dataset.reelSeek)].start+.001;this.segment(true);}));
  const state=()=>{const playing=!video.paused;strip?.classList.toggle('paused',!playing);button.innerHTML=uiIcon(playing?'Pause':'Play');button.title=t(playing?'暂停混剪':'播放混剪',playing?'Pause reel':'Play reel');button.setAttribute('aria-label',button.title);this.segment(true);};
  this.listen(video,'play',state);this.listen(video,'pause',state);this.listen(video,'seeked',()=>this.segment(true));this.segment(true);if(this.wanted&&!document.hidden)this.play();
 }
 play(){if(this.video&&!document.hidden&&!this.abort.signal.aborted)this.video.play().catch(()=>{if(!this.abort.signal.aborted){this.wanted=false;this.video.pause();}});}
 segment(force=false,cueIndex){
  const segments=this.reel?.segments||[];if(!segments.length)return;const time=this.video.currentTime,i=Number.isInteger(cueIndex)?cueIndex:Math.max(0,segments.findIndex(s=>time>=s.start&&time<s.end));if(i===this.selected&&!force)return;const changed=i!==this.selected;this.selected=i;const s=segments[i],label=this.root.querySelector('[data-reel-label]');
  if(changed||!label.textContent){label.href=dictionaryUrl(s.shot);label.innerHTML='<b>'+esc(s.shot)+'</b><strong>'+esc(t(s.name_zh,s.name_en.split('/')[0].trim()))+'</strong>'+(window.Shell.lang==='zh'?'<small>'+esc(s.name_en.split('/')[0].trim())+'</small>':'');const kind=this.root.querySelector('[data-reel-kind]');kind.textContent=t(s.kind==='ai'?'AI 成片':'白模',s.kind==='ai'?'AI film':'Blockout');kind.classList.toggle('ai',s.kind==='ai');}
  this.root.querySelectorAll('[data-reel-seek]').forEach((el,n)=>{const active=n===i;el.classList.toggle('is-current',active);el.setAttribute('aria-pressed',String(active));if(active){const progress=Math.max(0,Math.min(1,(time-s.start)/s.len)),bar=el.querySelector('i');bar.style.setProperty('--progress-from',progress*100+'%');bar.style.setProperty('--remaining',Math.max(.01,s.end-time)+'s');bar.style.animation='none';void bar.offsetWidth;bar.style.animation='';}});
 }
 dispose(){if(this.video)heroPlayback.set('t7-reel',{time:this.video.currentTime,wanted:this.wanted});this.abort.abort();this.observer?.disconnect();this.stopHover();this.timers.forEach(clearTimeout);this.frames.forEach(cancelAnimationFrame);this.video?.pause();}
}
