function directorLink(picks,label,attrs=''){if(!window.PREVIZ_URL)return '<button class="btn" data-previz '+attrs+' disabled title="'+t('导演台地址未配置','Director URL is not configured')+'">'+esc(label)+'</button>';const url=new URL(window.PREVIZ_URL,location.href);Object.entries(picks).forEach(([key,value])=>url.searchParams.set(key,value));return '<a class="btn primary" data-previz '+attrs+' href="'+esc(url.href)+'">'+uiIcon('Video')+esc(label)+'</a>';}
function feelingsMarkup(){return '<section class="feelings-page"><header class="landing-intro"><a class="text-button" href="'+esc(window.HOME_ENTRY?'#':document.querySelector('.shell-brand').href)+'">'+uiIcon('ArrowLeft')+t('首页','Home')+'</a><p class="eyebrow">'+t('先有情绪，再选镜头','Start with the feeling, then choose the shot')+'</p><h1>'+t('你想表达什么感觉？','What should the audience feel?')+'</h1><p>'+t('从一种感觉出发，看六个维度怎样一起工作。','Start with a feeling and see how six dimensions work together.')+'</p></header><div class="feelings-grid">'+feelings.map(item=>'<a class="feeling-card" data-feeling="'+esc(item.key)+'" href="#feeling-'+esc(item.key)+'">'+imageMarkup(publicAsset(byId.get(item.picks.movement.id)?.media?.poster),t(item.name_zh,item.name_en))+'<span><strong>'+esc(t(item.name_zh,item.name_en))+'</strong>'+(window.Shell.lang==='zh'?'<small lang="en">'+esc(item.name_en)+'</small>':'')+'<p>'+esc(t(item.desc_zh,feelingEnglish[item.key]?.desc||item.desc_zh))+'</p></span></a>').join('')+'</div></section>';}
