function showcaseMarkup(){return '<section class="showcase-page"><header class="landing-intro"><p class="eyebrow">'+t('从灰色白模到完整场景','From a gray blockout to a complete scene')+'</p><h1>'+t('成片合集','Finished shots')+'</h1><p>'+t('看同一个镜头怎样进入不同的故事。','See how the same camera move becomes part of a story.')+'</p></header>'+(showcaseItems.length?'<div class="showcase-grid">'+showcaseItems.map(showcaseCard).join('')+'</div>':'<p class="empty-state">'+t('第一批成片正在制作。先从词典或一种感觉开始。','The first finished shots are in production. Start with the dictionary or a feeling.')+'</p>')+followMarkup()+'</section>';}
