function showcasePaneMarkup(path,label,poster,role,muted=false){return '<figure><figcaption>'+esc(label)+'</figcaption>'+videoMarkup(publicAsset(path),label,publicAsset(poster),'showcase-video').replace('<video ','<video data-showcase-role="'+role+'" ').replace(role==='out'&&!muted?' muted':'__never__','')+'</figure>';}
function showcaseSectionMarkup(shot){const item=activeShowcase(shot),items=showcaseByShot[idOf(shot)],choice=showcaseChoice.get(idOf(shot)),textMode=choice?.text===true&&Boolean(item.compare),variant=textMode?item.compare:item,notes=variant.prompt_notes||[],facts=shotEnglishFacts[idOf(shot)];const pane=showcasePaneMarkup;const share=item.share?new URL(window.PREVIZ_URL||location.href,location.href):null;if(share){const encoded=item.share.replace(/^#/,'');share.hash=encoded.startsWith('s=')?encoded:'s='+encoded;share.searchParams.set('view','director');}return '<section class="showcase-example" data-showcase-id="'+esc(item.id)+'"><section data-showcase-section="compare"><header class="landing-section-heading"><div><p class="eyebrow">'+t('白模 → 成片','Blockout → Finished shot')+'</p><h2>'+esc(showcaseCaption(item,'theme_zh'))+'</h2>'+showcaseOriginalMarkup(item,'theme_zh')+showcaseDescriptionMarkup(item)+'</div>'+(items.length>1?'<label class="showcase-version-label">'+t('版本','Version')+'<select data-showcase-version aria-label="'+t('成片版本','Finished shot version')+'">'+items.map(version=>'<option value="'+esc(version.id)+'" '+(version.id===item.id?'selected':'')+'>'+esc(version.id)+'</option>').join('')+'</select></label>':'')+'</header>'+(item.compare?'<nav class="showcase-compare-switch" aria-label="'+t('生成方式对比','Generation comparison')+'"><button class="text-button" data-showcase-compare="reference" aria-pressed="'+!textMode+'">'+t('白模参考','Blockout reference')+'</button><button class="text-button" data-showcase-compare="text" aria-pressed="'+textMode+'">'+t('只用文字','Text only')+'</button></nav>':'')+'<div class="showcase-viewer" data-showcase-viewer>'+pane(textMode?item.out:item.ref,textMode?t('白模参考','Blockout reference'):t('白模','Blockout'),item.poster,'ref')+pane(variant.out,textMode?t('只用文字','Text only'):t('成片','Finished shot'),item.poster,'out')+'</div>'+showcaseTimelineMarkup(item)+'</section><section class="showcase-prompt-section" data-showcase-section="prompt"><header class="landing-section-heading"><div><h2>'+t('实际执行的提示词','The executed prompt')+'</h2><p class="subtle">'+esc(item.model)+(item.date?' · '+esc(item.date):'')+'</p></div><button class="copy-button" data-copy-showcase-prompt>'+uiIcon('Copy')+t('复制全文','Copy full prompt')+'</button></header><div class="showcase-prompt-layout"><p class="executed-prompt" data-showcase-prompt>'+annotatedPrompt(variant.prompt_text,notes)+'</p>'+(notes.length?'<aside class="prompt-notes"><h3>'+t('为什么关键 / 怎么写','Why it matters / How to write it')+'</h3><ol>'+notes.map((note,index)=>'<li data-note-index="'+index+'"><q>'+esc(note.match)+'</q><p>'+esc(t(note.note_zh,showcaseNotesEnglish(note)))+'</p></li>').join('')+'</ol></aside>':'')+'</div>'+(item.prompt_input_text&&!textMode?'<details class="showcase-input-fold"><summary>'+t('我输入的','What I typed')+'</summary><p class="executed-prompt">'+esc(item.prompt_input_text)+'</p></details>':'')+'</section><section class="showcase-meaning" data-showcase-section="meaning"><h2>'+t('这个镜头','About this shot')+'</h2>'+[['画面效果','What it conveys','effect'],['什么时候用','When to use it','conditions'],['不适合','When it does not fit','unsuitable']].map(([cn,english,key],i)=>'<section class="fact-row"><h3>'+t(cn,english)+'</h3><p '+(i===0?'class="entry-summary"':'')+'>'+esc(t(scienceText(shot[key]),facts?.[i]||scienceText(shot[key])))+'</p></section>').join('')+'</section>'+(share&&window.PREVIZ_URL?'<section class="showcase-director" data-showcase-section="director"><div><h2>'+t('在导演台改一改','Adjust it in the director')+'</h2><p>'+t('打开这条白模工程，调整自己的镜头。','Open this blockout project and adjust the shot.')+'</p></div><a class="btn primary" data-previz data-showcase-director href="'+esc(share.href)+'">'+uiIcon('Video')+t('打开白模工程','Open blockout project')+'</a></section>':'')+'</section>';}
function entryMarkup(shot){if(!activeShowcase(shot))return legacyEntryMarkup(shot);state.lensIndex=null;const i=shots.indexOf(shot);return '<article class="entry-page entry-with-showcase" data-entry-id="'+idOf(shot)+'"><header class="entry-header"><div class="entry-title"><p class="eyebrow">#'+idOf(shot)+' · '+sceneLabel(shot)+'</p><h1>'+esc(t(zh(shot),en(shot)))+'</h1>'+(window.Shell.lang==='zh'?'<p class="english-title" lang="en">'+esc(en(shot))+'</p>':'')+'</div><nav class="entry-nav"><button class="text-button" data-entry-move="-1" '+(i===0?'disabled':'')+'>'+uiIcon('ArrowLeft')+t('上一条','Previous')+'</button><button class="text-button" data-entry-move="1" '+(i===shots.length-1?'disabled':'')+'>'+t('下一条','Next')+uiIcon('ArrowRight')+'</button></nav></header>'+showcaseSectionMarkup(shot)+'<section class="showcase-legacy" data-showcase-section="legacy"><h2>'+t('词典演示与提示词','Dictionary demonstrations and prompts')+'</h2><div class="showcase-legacy-actions"><button class="text-button" data-select-compare="'+idOf(shot)+'" aria-pressed="'+state.compare.includes(idOf(shot))+'">'+(state.compare.includes(idOf(shot))?t('移出对比','Remove from comparison'):t('加入对比','Add to comparison'))+'</button>'+previzMarkup({[shot.categoryKey]:idOf(shot)})+'</div>'+viewerMarkup(shot)+(shot.categoryKey==='lens'?lensControlsMarkup(shot):'')+'<div class="entry-body"><section class="entry-facts">'+relatedMarkup(shot)+'</section><aside class="entry-prompts"><h2>'+t('生成提示词','Generation prompts')+'</h2>'+promptMarkup(shot,'seedance')+promptMarkup(shot,'h3')+referencesMarkup(shot)+'</aside></div></section>'+communityMarkup('#'+idOf(shot)+' '+zh(shot))+'</article>';}
function startShowcase(){const item=activeShowcase(byId.get(detailId)),root=$('reader').querySelector('.showcase-example');if(!item||!root)return;showcaseSession=new MediaSession(root.querySelector('[data-showcase-viewer]'),root.querySelector('.shared-timeline'),{...item.render,visibleOnly:false,localized:true,longest:true,pauseOnScrub:true});showcaseSession.master=root.querySelector('[data-showcase-role="out"]');showcaseSession.syncTimeline();}
// Hero shares the detail player's synchronization; memory survives route/language redraws.
function replaceShowcase(){const shot=byId.get(detailId);if(!shot)return;const root=$('reader').querySelector('.showcase-example');showcaseSession?.release();showcaseSession=null;unwatchImages(root);root.outerHTML=showcaseSectionMarkup(shot);watchImages($('reader'));startShowcase();}
let route={type:'home'},compareIds=['034','054'],comparePreset=-1,fullscreenRestoreView=null,lastFocus=null,searchResults=[],searchIndex=0,searchSession=null,drawerOpen=false;
const directoryExpanded=new Set();let directoryFocusKey=null;
state.motionGroup='all';state.lensIndex=null;state.composerPromptLanguage={seedance:document.documentElement.dataset.lang||'zh',h3:document.documentElement.dataset.lang||'zh'};
function navigate(hash){if(location.hash===hash){renderRoute();return;}location.hash=hash;}
function openShot(id){id=normId(id);if(byId.has(id)){closeSearch();closeDirectory();if(window.HOME_ENTRY){location.assign(dictionaryUrl(id));return;}navigate('#'+id);}}
function openCompare(ids=['034','054']){const valid=ids.map(normId).filter(id=>byId.has(id)).slice(0,2);navigate('#compare='+(valid.length===2?valid:['034','054']).join(','));}
function releasePage(){stopHover();centreObserver?.disconnect();centreCards.clear();detailSession?.release();compareSession?.release();composerSession?.release();showcaseSession?.release();showcaseSession=null;heroCleanup?.();heroCleanup=null;detailSession=compareSession=composerSession=null;fullscreenRestoreView=null;unwatchImages($('reader'));if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});}
function readRoute(){const hash=decodeURIComponent(location.hash.slice(1));if(hash==='feelings')return {type:'feelings'};if(hash.startsWith('feeling-')&&feelingByKey.has(hash.slice(8)))return {type:'feeling',key:hash.slice(8)};if(hash==='showcase')return {type:'showcase'};if(/^\d{1,3}$/.test(hash)&&byId.has(normId(hash)))return {type:'entry',id:normId(hash)};if(hash==='compose')return {type:'compose'};if(hash.startsWith('compare=')){const ids=hash.slice(8).split(',').map(normId).filter(id=>byId.has(id));return {type:'compare',ids:ids.length>=2?ids.slice(0,2):['034','054']};}if(hash.startsWith('category-')&&categoryDefs.some(category=>category.key===hash.slice(9)))return {type:'category',key:hash.slice(9)};return {type:window.HOME_ENTRY?'landing':'home'};}
function renderRoute(){pageHasRendered=true;releasePage();route=readRoute();detailId=route.type==='entry'?route.id:null;const category=detailId?byId.get(detailId)?.categoryKey:route.type==='category'?route.key:null;if(category&&!directoryFocusKey)directoryExpanded.add(category);const fullPage=['landing','feelings','feeling','showcase'].includes(route.type);document.body.dataset.route=route.type;document.body.dataset.page=route.type;document.body.dataset.mode=route.type==='compose'?'compose':'dictionary';document.body.classList.toggle('compose-mode',route.type==='compose');document.body.classList.toggle('compare-mode',route.type==='compare');document.body.classList.toggle('public-page',fullPage);$('sidebar').hidden=fullPage;if(fullPage)closeDirectory();window.Shell.setPage(window.HOME_ENTRY&&['landing','feelings','feeling','showcase'].includes(route.type)?'landing':'dictionary');$('composer-toggle')?.setAttribute('aria-pressed',String(route.type==='compose'));$('reader').innerHTML=route.type==='entry'?entryMarkup(byId.get(route.id)):route.type==='category'?categoryMarkup(route.key):route.type==='compare'?compareMarkup(route.ids):route.type==='compose'?composeMovedMarkup():route.type==='landing'?landingMarkup():route.type==='feelings'?feelingsMarkup():route.type==='feeling'?feelingMarkup(route.key):route.type==='showcase'?showcaseMarkup():homeMarkup();renderDirectory();updateMobileNav();watchImages($('reader'));watchCards();if(route.type==='entry'){startEntry();startShowcase();}else if(route.type==='compare')startCompare();else if(route.type==='compose'){}else if(route.type==='landing')startHero();window.scrollTo({top:0,behavior:'instant'});const focus=directoryFocusKey?$('directory').querySelector('[data-category="'+directoryFocusKey+'"]'):$('reader');directoryFocusKey=null;focus?.focus({preventScroll:true});}
function renderDirectory(){const root=$('directory');if(!root)return;const query=($('directory-search')?.value||'').trim().toLowerCase(),current=detailId?byId.get(detailId):null;unwatchImages(root);root.innerHTML='<button class="directory-home '+(route.type==='home'?'active':'')+'" data-home>总览 <span>105</span></button>'+categoryDefs.map(category=>{const items=shots.filter(shot=>shot.categoryKey===category.key),expanded=directoryExpanded.has(category.key);return '<section class="directory-category" data-directory-category="'+category.key+'" data-expanded="'+expanded+'"><button class="directory-category-button '+((current?.categoryKey===category.key||route.key===category.key)?'active':'')+'" data-category="'+category.key+'" aria-controls="directory-entries-'+category.key+'" aria-expanded="'+expanded+'">'+categoryIcon(category.key)+'<span>'+esc(category.label)+'</span><small>'+items.length+'</small><span class="directory-chevron">'+uiIcon(expanded?'ChevronUp':'ChevronDown')+'</span></button><div class="directory-entries" id="directory-entries-'+category.key+'" '+(!expanded?'hidden':'')+'>'+items.filter(shot=>!query||indexed.get(idOf(shot)).includes(query)).map(shot=>'<button class="directory-entry '+(detailId===idOf(shot)?'active':'')+'" data-open="'+idOf(shot)+'" '+(detailId===idOf(shot)?'aria-current="page"':'')+'><span>'+esc(zh(shot))+'</span><small lang="en">'+esc(en(shot))+'</small></button>').join('')+'</div></section>';}).join('');if(current)requestAnimationFrame(()=>{const active=root.querySelector('[aria-current="page"]');if(active){const rect=active.getBoundingClientRect(),scrollRoot=$('sidebar'),container=scrollRoot.getBoundingClientRect();if(rect.top<container.top+50||rect.bottom>container.bottom-20)active.scrollIntoView({block:'center',behavior:'instant'});}});}
function openDirectory(){drawerOpen=true;document.body.classList.add('directory-open');$('sidebar-backdrop').hidden=false;$('menu-toggle')?.setAttribute('aria-expanded','true');$('directory-close')?.focus();}
function closeDirectory(){drawerOpen=false;document.body.classList.remove('directory-open');if($('sidebar-backdrop'))$('sidebar-backdrop').hidden=true;$('menu-toggle')?.setAttribute('aria-expanded','false');}
function homeMarkup(){const starts=['033','034','054'],english={size:'Shot Size',angle:'Camera Angle',lens:'Focal Length',movement:'Camera Movement',focus:'Depth of Field',composition:'Composition'},pictures={size:['003','006','008'],angle:['013'],lens:['029'],movement:['034'],focus:['078'],composition:['090']},pairs=[{ids:['034','054'],label:'推近 vs 变焦'},{ids:['044','036'],label:'摇 vs 横移'},{ids:['045','037'],label:'俯仰 vs 升降'}];return '<section class="home-page"><header class="home-heading"><h1>六个维度，读懂一个镜头</h1><p>拍多大 · 从哪看 · 怎样呈现空间 · 怎样移动 · 哪里清楚 · 怎样摆放</p></header><div class="dimension-grid">'+categoryDefs.map(category=>'<button class="dimension-card" data-category="'+category.key+'"><span class="dimension-media '+(category.key==='size'?'dimension-size-triptych':'')+'">'+pictures[category.key].map(id=>imageMarkup(byId.get(id)?.media?.poster,zh(byId.get(id)))).join('')+'</span><span class="dimension-copy"><span class="dimension-title">'+esc(category.label)+'</span><span class="dimension-english" lang="en">'+english[category.key]+'</span><small>'+shots.filter(shot=>shot.categoryKey===category.key).length+' 条</small><span class="dimension-question">'+esc(category.question)+'？</span></span></button>').join('')+'</div><div class="home-bottom"><section class="home-start"><header class="section-heading"><h2>从这里开始</h2></header><div class="start-grid shot-grid">'+starts.map(id=>cardMarkup(byId.get(id))).join('')+'</div></section><section class="home-confusables"><header class="section-heading"><h2>易混对照</h2></header><div class="home-comparison-chips">'+pairs.map(pair=>'<button class="comparison-card" data-open-compare="'+pair.ids.join(',')+'"><strong>'+pair.label+'</strong><span>'+uiIcon('ChevronRight')+'</span></button>').join('')+'</div></section></div>'+communityMarkup('')+'</section>';}
function categoryMarkup(key){const category=categoryDefs.find(item=>item.key===key),items=shots.filter(shot=>shot.categoryKey===key);state.category=key;filtered=items;const groups=key==='movement'?motionGroups.filter(group=>state.motionGroup==='all'||group.key===state.motionGroup):[{key,label:category.label,ids:items.map(idOf),note:''}];return '<section class="category-page" data-category-page="'+key+'"><header class="category-header"><div>'+categoryIcon(key)+'<h1>'+esc(category.label)+'</h1><span>'+items.length+' 条</span></div><p>'+esc(category.question)+'</p>'+guideButtonMarkup()+'</header>'+(key==='movement'?'<nav class="group-filters" aria-label="运镜主要驱动">'+[{key:'all',label:'全部',ids:items.map(idOf)},...motionGroups].map(group=>'<button data-motion-group="'+group.key+'" aria-pressed="'+(state.motionGroup===group.key)+'">'+group.label+' <small>'+group.ids.length+'</small></button>').join('')+'</nav>':'')+groups.map(group=>'<section class="category-section" data-motion-section="'+group.key+'"><header class="section-heading"><h2>'+esc(group.label)+'</h2><p>'+esc(group.note)+'</p></header><div class="shot-grid">'+group.ids.map(id=>byId.get(id)).filter(Boolean).map(cardMarkup).join('')+'</div></section>').join('')+'</section>';}
function toggleCompareSelection(id){id=normId(id);if(state.compare.includes(id))state.compare=state.compare.filter(value=>value!==id);else if(state.compare.length<2)state.compare.push(id);else{toast('最多选择两条，请先移除一条');return;}document.querySelectorAll('[data-select-compare]').forEach(button=>{const selected=state.compare.includes(button.dataset.selectCompare);button.setAttribute('aria-pressed',String(selected));button.classList.toggle('selected',selected);button.innerHTML=button.classList.contains('card-select')?uiIcon(selected?'Check':'Plus'):(uiIcon(selected?'Check':'Plus')+(selected?'移出对比':'加入对比'));});renderTray();}
function renderTray(){const tray=$('compare-tray'),root=$('compare-tray-items');if(!tray||!root)return;unwatchImages(root);tray.hidden=!state.compare.length;root.innerHTML=state.compare.map(id=>byId.get(id)).filter(Boolean).map(shot=>'<article class="compare-tray-item">'+imageMarkup(shot.media?.poster,zh(shot))+'<span>'+esc(zh(shot))+'</span><button data-remove-compare="'+idOf(shot)+'" aria-label="移除'+esc(zh(shot))+'">'+uiIcon('X')+'</button></article>').join('');$('compare-start').disabled=state.compare.length!==2;$('compare-start').textContent=state.compare.length===2?'开始对比':'再选一条';watchImages(root);}
function promptMarkup(shot,model){const language=state.promptLanguage[model],name=model==='seedance'?'Seedance':'H3';return '<section class="drawer-prompt" data-prompt-block="'+model+'"><div class="output-heading"><h3>'+name+'</h3></div><p class="prompt-text" lang="'+language+'">'+esc(getPrompt(shot,model,language))+'</p><div class="prompt-footer"><button class="copy-button" data-copy-prompt="'+idOf(shot)+':'+model+'">'+uiIcon('Copy')+'复制</button></div></section>';}
