function rowMarkup(label,value){const content=scienceText(value);return content?'<section class="fact-row"><h3>'+esc(label)+'</h3><p>'+esc(content)+'</p></section>':'';}
function referencesMarkup(shot){const references=shot.references||[];return '<details class="detail-reference-fold"><summary>Blender 做法'+uiIcon('ChevronDown')+'</summary>'+rowMarkup('Blender 做法',shot.blender)+'</details>'+(references.length?'<section class="official-references" aria-label="参考资料"><h2>参考资料</h2><ul>'+references.map(reference=>'<li><a href="'+esc(reference.url)+'" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer"><span>'+esc(reference.publisher)+' · '+esc(reference.title)+'</span>'+uiIcon('MoveUpRight')+'</a><p>'+esc(reference.note)+'</p></li>').join('')+'</ul></section>':'');}
