function legacyEntryMarkup(shot){state.lensIndex=null;const i=shots.indexOf(shot);return '<article class="entry-page" data-entry-id="'+idOf(shot)+'"><header class="entry-header"><div class="entry-title"><p class="eyebrow">'+esc(shot.category)+' · '+idOf(shot)+' · '+sceneLabel(shot)+'</p><h1>'+esc(zh(shot))+'</h1><p class="english-title" lang="en">'+esc(en(shot))+'</p></div><p class="entry-summary">'+esc(cleanCardText(shot.effect))+'</p><nav class="entry-nav"><button class="text-button" data-entry-move="-1" '+(i===0?'disabled':'')+'>'+uiIcon('ArrowLeft')+'上一条</button><button class="text-button" data-entry-move="1" '+(i===shots.length-1?'disabled':'')+'>下一条'+uiIcon('ArrowRight')+'</button><button class="text-button" data-select-compare="'+idOf(shot)+'" aria-pressed="'+state.compare.includes(idOf(shot))+'">'+(state.compare.includes(idOf(shot))?'移出对比':'＋ 加入对比')+'</button>'+previzMarkup({[shot.categoryKey]:idOf(shot)})+'</nav></header>'+viewerMarkup(shot)+(shot.categoryKey==='lens'?lensControlsMarkup(shot):'')+'<div class="entry-body"><section class="entry-facts">'+rowMarkup('画面效果',shot.effect)+rowMarkup('什么时候用',shot.conditions)+rowMarkup('不适合',shot.unsuitable)+relatedMarkup(shot)+'</section><aside class="entry-prompts"><h2>生成提示词</h2>'+promptMarkup(shot,'seedance')+promptMarkup(shot,'h3')+referencesMarkup(shot)+'</aside></div>'+communityMarkup('#'+idOf(shot)+' '+zh(shot))+'</article>';}
function viewerMarkup(shot){const motion=Boolean(shot.media?.video),cameras=['diagram','sideDiagram'].filter(key=>shot.media?.[key]);if(!cameras.includes(state.detailDiagram))state.detailDiagram=cameras[0]||'diagram';state.detailView=innerWidth<760?'main':motion&&cameras.length?'split':'main';const pane=(key,label)=>{let media=mediaMarkup(shot,key);if(media.includes('class="media-frame '))media=media.replace('<div class="media-frame ','<div data-media-surface="'+key+'" class="media-frame ').replace(/<\/div>$/,'<button class="media-expand-button" data-media-fullscreen="'+key+'" aria-label="全屏查看'+label+'">'+uiIcon('Expand')+'</button>'+(key==='main'&&shot.categoryKey==='size'?cropLineMarkup(shot):'')+'</div>');return '<section class="viewer-pane" data-viewer-pane="'+key+'" '+(state.detailView==='split'?(key!=='main'&&key!==state.detailDiagram?'hidden':''):(key!=='main'?'hidden':''))+'><header class="viewer-pane-header">'+(key==='main'?'<h3>画面</h3>':key===state.detailDiagram?cameraTabsMarkup(cameras):'<h3>'+label+'</h3>')+'</header>'+media+(key!=='main'?legendMarkup(shot):'')+'</section>';};const extra=!motion?(shot.categoryKey==='size'?sizePanelMarkup(shot):shot.categoryKey==='lens'?lensPlanPanelMarkup(shot):kind(shot)!=='unavailable'?staticPanelMarkup(shot):''):'';return '<section class="detail-viewer" data-entry-viewer><div class="viewer-toolbar"><nav class="viewer-tabs mobile-view-tabs" aria-label="演示视角">'+[{key:'main',label:'画面'},...cameras.map(key=>({key,label:key==='diagram'?'俯视':'侧视'}))].map(item=>'<button data-viewer-tab="'+item.key+'" aria-pressed="'+(state.detailView===item.key)+'">'+item.label+'</button>').join('')+'</nav>'+guideButtonMarkup()+'<button class="viewer-fullscreen-button" data-viewer-fullscreen aria-pressed="false">'+uiIcon('Expand')+'全屏</button></div><div class="detail-media-stage entry-media-layout '+(motion?'viewer-split':'static-media-layout')+'" data-view="'+state.detailView+'" data-layout="'+(motion&&state.detailView==='split'?'split':'single')+'">'+pane('main','画面')+cameras.map(key=>pane(key,key==='diagram'?'俯视':'侧视')).join('')+extra+'</div>'+(motion?timelineMarkup(zh(shot),shot):shot.categoryKey==='size'?'<p class="media-static-notice">景别比较画框里的范围；本组保持同一真实机位与 50mm，以有效画框裁切示意。</p>':'')+'</section>';}
