function legendMarkup(shot){const id=idOf(shot),fixedZoom=['054','055','056'].includes(id),note=fixedZoom?'机位不变，视角收放':id==='051'?'原地转向后变焦':id==='052'?'改变方位，同时变焦':id==='057'?'相机距离与焦距反向配合':'线框是相机视锥；线与箭头是路径',start=fixedZoom?(shot.render?.lens_start<shot.render?.lens_end?'广角':'长焦'):'起始机位',end=fixedZoom?(shot.render?.lens_start<shot.render?.lens_end?'长焦':'广角'):'结束机位';return '<p class="diagram-legend"><span class="legend-start">'+start+'</span><span class="legend-end">'+end+'</span><small>'+note+'</small></p>';}
function startEntry(){const shot=byId.get(detailId),root=$('reader');watchImages(root);if(shot.media?.video){const viewer=root.querySelector('[data-entry-viewer]');detailSession=new MediaSession(viewer.querySelector('.detail-media-stage'),viewer.querySelector('.shared-timeline'),{...shot.render,visibleOnly:true});if(!reducedMotion.matches&&!activeShowcase(shot))detailSession.play();}}
function setViewerTab(view){const viewer=$('reader').querySelector('[data-entry-viewer]');if(!viewer)return;state.detailView=view;viewer.querySelectorAll('[data-viewer-pane]').forEach(pane=>pane.hidden=view==='split'?pane.dataset.viewerPane!=='main'&&pane.dataset.viewerPane!==state.detailDiagram:pane.dataset.viewerPane!==view);viewer.querySelectorAll('[data-viewer-tab]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.viewerTab===view)));const stage=viewer.querySelector('.detail-media-stage');stage.dataset.view=view;stage.dataset.layout=view==='split'?'split':'single';stage.classList.toggle('single-view',view!=='split');const cameraTabs=viewer.querySelector('.viewer-camera-tabs'),header=viewer.querySelector('[data-viewer-pane="'+state.detailDiagram+'"] .viewer-pane-header');if(cameraTabs&&header){header.replaceChildren(cameraTabs);cameraTabs.querySelectorAll('[data-camera-view]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.cameraView===state.detailDiagram)));}viewer.querySelectorAll('.entry-aside').forEach(panel=>panel.hidden=view!=='main');watchImages(viewer);detailSession?.syncVisibility();}
