function restoreViewerLayout(){const restore=fullscreenRestoreView;fullscreenRestoreView=null;if(restore?.id===detailId){state.detailDiagram=restore.diagram;setViewerTab(restore.view);}}
function currentViewer(){return $('reader').querySelector('.detail-viewer,[data-comparison-viewer],[data-composer-viewer]');}
function syncFullscreen(){const viewer=currentViewer(),native=document.fullscreenElement===viewer,wasNative=viewer?.classList.contains('viewer-fullscreen');viewer?.classList.toggle('viewer-fullscreen',native);if(wasNative&&!native)restoreViewerLayout();const button=viewer?.querySelector('[data-viewer-fullscreen]');if(button){button.innerHTML=uiIcon(native||viewer.classList.contains('viewer-expanded')?'Minimize':'Expand')+(native?'退出全屏':viewer.classList.contains('viewer-expanded')?'还原':'全屏');button.setAttribute('aria-pressed',String(native||viewer.classList.contains('viewer-expanded')));}}
async function toggleViewerFullscreen(){const viewer=currentViewer();if(!viewer)return;if(document.fullscreenElement===viewer){await document.exitFullscreen();return;}if(viewer.classList.contains('viewer-expanded')){viewer.classList.remove('viewer-expanded');restoreViewerLayout();syncFullscreen();return;}try{if(!viewer.requestFullscreen)throw Error('unsupported');await viewer.requestFullscreen();if(viewer.isConnected)syncFullscreen();}catch(_){if(!viewer.isConnected)return;viewer.classList.add('viewer-expanded');syncFullscreen();toast('浏览器未进入全屏，已放大查看区域');}}
