function cropLineMarkup(shot){const crop=shot.render?.crop,lower=crop?crop.centerZ-crop.frameHeight/2:0;return '<div class="crop-line" data-crop-line style="bottom:0"><span>画框下缘 '+lower.toFixed(2)+' m</span></div>';}
function sizePanelMarkup(shot){const crop=shot.render?.crop||{centerZ:.9,frameHeight:1.8},low=crop.centerZ-crop.frameHeight/2,high=crop.centerZ+crop.frameHeight/2,y=z=>220-z/1.8*190,ticks=[['头顶',1.8],['肩',1.5],['胸',1.3],['腰',1],['膝',.5],['脚',0]];return '<aside class="entry-aside size-panel"><h2>同类对照</h2><div class="size-panel-content"><svg class="size-ruler" data-size-ruler viewBox="0 0 180 240" role="img" aria-label="1.8米胶囊代理，琥珀线为当前画框上下边界"><rect x="34" y="30" width="44" height="190" rx="22" class="ruler-actor"/><path d="M56 45v13" class="ruler-direction"/>'+ticks.map(([label,z])=>'<g class="ruler-tick"><path d="M82 '+y(z)+'H126"/><text x="132" y="'+(y(z)+4)+'">'+label+'</text></g>').join('')+'<rect x="29" y="'+Math.max(30,y(high))+'" width="54" height="'+Math.max(1,Math.min(220,y(low))-Math.max(30,y(high)))+'" class="ruler-crop"/><path class="ruler-crop-line" d="M27 '+Math.max(30,Math.min(220,y(low)))+'H126"/><text x="30" y="236">1.8 m 胶囊代理</text></svg><div class="size-ladder" data-size-ladder>'+shots.filter(item=>item.categoryKey==='size').map(item=>'<button data-open="'+idOf(item)+'" data-size-step="'+idOf(item)+'" aria-current="'+(idOf(item)===idOf(shot)?'true':'false')+'">'+imageMarkup(item.media?.poster,zh(item))+'<span>'+esc(zh(item))+'</span></button>').join('')+'</div></div><p class="small-note">刻度是人体部位参照；琥珀范围按实际演示画框标示。</p></aside>';}
function staticPanelMarkup(shot){return '<aside class="entry-aside static-comparison-panel"><h2>同类对照</h2><div class="static-comparison-list">'+shots.filter(item=>item.categoryKey===shot.categoryKey).map(item=>'<button data-open="'+idOf(item)+'" class="'+(idOf(item)===idOf(shot)?'active':'')+'">'+imageMarkup(item.media?.poster,zh(item))+'<span>'+esc(zh(item))+'</span></button>').join('')+'</div></aside>';}
function lensPlanSvg(index=null,shot=null){const lenses=overviewData.lenses||[],selected=lenses[index],actual=selected||{mm:shot?.render?.lens_start||50,distance:Math.hypot(...(shot?.render?.camera_start||[0,-8,1]).map((n,i)=>n-(shot?.render?.target_start||[0,0,1])[i]))},actorY=32,scale=10;return '<svg class="lens-plan" data-lens-plan data-focal="'+actual.mm+'" data-distance="'+actual.distance+'" viewBox="0 0 280 290" role="img" aria-label="'+actual.mm+'毫米，相机距离'+actual.distance.toFixed(2)+'米，主体大小保持一致"><defs><pattern id="lens-grid" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M20 0H0V20" fill="none" stroke="currentColor" opacity=".12"/></pattern></defs><rect width="280" height="270" fill="url(#lens-grid)"/><rect x="120" y="18" width="40" height="28" rx="14" class="lens-actor"/><path d="M140 46v212" class="lens-axis"/>'+lenses.map((item,i)=>{const cy=actorY+item.distance*scale,half=item.distance*18/item.mm*scale;return '<g class="lens-camera '+(index===i?'active':'')+'" data-lens-camera="'+i+'"><path d="M140 '+cy+' '+(140-half)+' '+actorY+' '+(140+half)+' '+actorY+'Z" class="lens-cone"/><rect x="134" y="'+(cy-4)+'" width="12" height="9" rx="1"/><text x="165" y="'+(cy+4)+'">'+item.mm+' mm · '+item.distance+' m</text></g>';}).join('')+'<text x="140" y="280" text-anchor="middle">'+actual.mm+' mm · 视角 '+(2*Math.atan(18/actual.mm)*180/Math.PI).toFixed(1)+'°</text></svg>';}
function lensPlanPanelMarkup(shot){const shared=['026','027','028','029'].includes(idOf(shot)),i=shared?overviewData.lenses?.findIndex(item=>item.mm===shot.render?.lens_start):-1;if(i>=0)state.lensIndex=i;const plan=idOf(shot)==='031'?'<p class="lens-special-note">鱼眼采用曲线投影，视角随投影方式变化。下方五档焦距对照使用直线投影，供空间关系比较。</p>':lensPlanSvg(state.lensIndex,shot);return '<aside class="entry-aside lens-panel"><h2>机位与视角</h2><div data-lens-plan-host>'+plan+'</div><p class="small-note" data-lens-distance>'+((state.lensIndex!=null)?'相机距离 '+overviewData.lenses[state.lensIndex].distance+' m':'本条专项画面')+'</p></aside>';}
function lensControlsMarkup(shot){const lenses=overviewData.lenses||[];return '<section class="lens-controls" data-lens-controls><div class="lens-range-wrap"><label for="lens-range">同景别焦距对照 <output id="lens-value">'+(state.lensIndex!=null?lenses[state.lensIndex].mm+' mm':'专项画面')+'</output></label><input id="lens-range" data-lens-range type="range" min="0" max="'+(lenses.length-1)+'" step="1" value="'+(state.lensIndex??2)+'" aria-label="五档焦距对照"><div class="lens-stops">'+lenses.map((item,i)=>'<button data-lens-index="'+i+'" aria-pressed="'+(state.lensIndex===i)+'">'+item.mm+' mm</button>').join('')+'</div></div><div class="lens-strip" data-lens-strip>'+lenses.map((item,i)=>'<button data-lens-index="'+i+'" aria-pressed="'+(state.lensIndex===i)+'">'+imageMarkup(item.path,item.mm+'mm，距离'+item.distance+'m')+'<span>'+item.mm+' mm</span></button>').join('')+'</div><p class="small-note">共用对照为 24 / 35 / 50 / 85 / 135 mm，调整机位距离以保持主体大小。'+(state.lensIndex==null?'本条先显示自身专项画面；操作滑块后切换共用对照。':'')+'</p></section>';}
function changeLens(index){const item=overviewData.lenses?.[index],shot=byId.get(detailId),root=$('reader'),image=root.querySelector('[data-media-surface="main"] img');if(!item||!image)return;state.lensIndex=index;image.src=item.path;image.alt=item.mm+'mm同景别对照';delete image.dataset.src;$('lens-range').value=index;setText('lens-value',item.mm+' mm');root.querySelector('[data-lens-distance]').textContent='相机距离 '+item.distance+' m';root.querySelector('[data-lens-plan-host]').innerHTML=lensPlanSvg(index,shot);root.querySelectorAll('[data-lens-index]').forEach(button=>button.setAttribute('aria-pressed',String(Number(button.dataset.lensIndex)===index)));positionGuide(root.querySelector('[data-guide-main]'));}
