function compareMarkup(ids){compareIds=ids;comparePreset=comparisons.findIndex(item=>[item.ids[0],item.ids[item.ids.length-1]].every(id=>ids.includes(id)));const items=ids.map(id=>byId.get(id)),options=selected=>shots.map(shot=>'<option value="'+idOf(shot)+'" '+(idOf(shot)===selected?'selected':'')+'>'+idOf(shot)+' · '+esc(zh(shot))+'</option>').join(''),preset=comparisons[comparePreset],conclusion=scienceText(preset?.note)||items.map(shot=>zh(shot)+'：'+scienceText(shot.confusable||shot.effect)).join('；');return '<section class="compare-page"><header class="compare-header"><p class="eyebrow">把驱动和效果放在一起看</p><h1>并排对比</h1><button class="text-button" data-home>← 返回总览</button></header><nav id="comparison-presets" class="comparison-presets">'+comparisons.map((item,i)=>'<button data-preset="'+i+'" aria-pressed="'+(comparePreset===i)+'">'+esc(item.title)+'</button>').join('')+'</nav><section data-comparison-viewer><div class="compare-toolbar">'+guideButtonMarkup()+'<button data-viewer-fullscreen>'+uiIcon('Expand')+'全屏</button></div><div class="compare-media-grid comparison-panes">'+items.map((shot,i)=>'<article class="comparison-pane"><header><label><select data-compare-side="'+i+'" aria-label="'+(i?'右':'左')+'侧条目">'+options(idOf(shot))+'</select></label><p lang="en">'+esc(en(shot))+'</p></header><div class="compare-main">'+mediaMarkup(shot)+'</div>'+(shot.media?.diagram?'<div class="compare-diagram"><h3>俯视机位</h3>'+mediaMarkup(shot,'diagram')+legendMarkup(shot)+'</div>':'<p class="media-static-notice">静图 · 此条没有动画播放</p>')+'<button class="text-button" data-open="'+idOf(shot)+'">打开条目 →</button></article>').join('')+'</div>'+(items.some(shot=>shot.media?.video)?timelineMarkup('并排对比',items.find(shot=>shot.media?.video)):'<p class="comparison-static-notice">两条都是静图，可直接比较画面范围与空间关系。</p>')+'</section><p class="comparison-conclusion" data-comparison-conclusion>'+esc(conclusion)+'</p></section>';}
