function composeMovedMarkup(){return '<section class="compose-page compose-moved"><header class="compose-header"><h1>'+t('组合镜头搬到了导演台','Shot composing moved to the director')+'</h1><p>'+t('在导演台里选景别、角度、焦距、运镜，画面会实时变化，并直接给出 Seedance / H3 提示词。','In the director every size, angle, lens and movement you pick updates the live frame and the Seedance / H3 prompts.')+'</p><a class="btn primary" href="'+esc(composeUrl())+'">'+uiIcon('Video')+t('打开导演台','Open the director')+'</a></header></section>';}
