function composerMarkup(){const fields=state.composerFields[state.composerLanguage],movement=byId.get(state.composerSelection.movement),field=(key,label,type='text')=>'<label class="composer-field">'+label+'<input data-composer-field="'+key+'" type="'+type+'" '+(type==='number'?'min="1" max="30" step="0.5"':'')+' value="'+esc(fields[key])+'"></label>';return '<section class="compose-page"><header class="compose-header"><h1>镜头组合</h1><p>依次选择六个维度，整理起幅、落幅与提示词。</p>'+previzMarkup(state.composerSelection)+'</header><div class="composer-layout"><nav class="composer-steps" aria-label="六步选镜头">'+categoryDefs.map((category,i)=>{const selected=state.composerSelection[category.key],shot=byId.get(selected);return '<section class="composer-step '+(i===state.composerStep?'active':'')+'" data-composer-section="'+i+'"><button class="composer-step-heading" data-composer-step="'+i+'" aria-expanded="'+(i===state.composerStep)+'"><span class="step-number">'+(i+1)+'</span><span><small>'+esc(category.label)+(category.key==='composition'?' · 可选':'')+'</small><strong>'+esc(shot?zh(shot):'不额外指定')+'</strong></span><span class="step-check">'+(selected?uiIcon('Check'):'')+'</span></button><div class="composer-options" '+(i!==state.composerStep?'hidden':'')+'>'+(category.key==='composition'?'<button data-composer-choice="" data-composer-category="composition" aria-pressed="'+!selected+'">不额外指定</button>':'')+composerChoices(category.key).map(item=>'<button class="composer-choice" data-composer-choice="'+idOf(item)+'" data-composer-category="'+category.key+'" aria-pressed="'+(selected===idOf(item))+'">'+imageMarkup(item.media?.poster,zh(item))+'<span>'+esc(zh(item))+'</span></button>').join('')+'</div></section>';}).join('')+'<button class="text-button composer-reset" data-composer-reset>清空重选</button></nav><section class="composer-preview-column"><section class="composer-preview" data-composer-viewer><div class="composer-preview-heading"><h2>'+esc(zh(movement))+' · 现有运镜示意</h2>'+guideButtonMarkup()+'<button data-viewer-fullscreen>'+uiIcon('Expand')+'全屏</button></div><div class="composer-media card-media media-frame" data-guide-main>'+mediaMarkup(movement).replace(/^<div class="media-frame[^>]*>|<\/div>$/g,'')+'</div>'+(movement.media?.video?timelineMarkup('组合预览',movement):'')+'<p class="composer-preview-notice" data-composer-preview-notice>预览仅显示所选运镜的现有媒体。景别、角度、焦距、景深、构图及自定义起落幅、时长没有组合渲染到此画面。</p></section><section class="slate-card"><div class="slate-stripes"></div><header><h2>S01</h2><span data-slate-duration></span></header><div class="slate-tags" data-slate-tags></div><div class="composer-fields">'+field('subject','主体与环境')+field('start','起幅')+field('end','落幅')+field('duration','时长（秒）','number')+'<details><summary>主体动作与保留属性</summary>'+field('action','主体动作')+field('retention','保留属性')+'</details></div></section></section><aside class="composer-output-column"><h2>输出</h2>'+composerResultMarkup('seedance')+composerResultMarkup('h3')+'<section class="composer-result"><div class="output-heading"><h3>镜头表一行</h3><button class="copy-button" data-copy-output="shot-description">'+uiIcon('Copy')+'复制</button></div><div class="shot-table-wrap"><table class="shot-table" data-shot-table><thead><tr>'+['景别','角度','焦距','运镜','起幅→落幅','时长'].map(label=>'<th>'+label+'</th>').join('')+'</tr></thead><tbody><tr data-shot-table-row></tr></tbody></table></div><textarea id="shot-description" class="visually-hidden" readonly aria-label="镜头表一行"></textarea></section><button class="action-button copy-all-button" data-copy-all>复制全部</button></aside></div></section>';}
