function composerOutput(model,language){const chosen=chosenShots(),fields=state.composerFields[language],duration=Math.max(1,Math.min(30,Number(fields.duration)||4)),english=language==='en';return (english?['Subject and setting: '+text(fields.subject)+'.','Opening frame: '+text(fields.start)+'.','Shot duration: '+duration+' seconds.',...chosen.map(shot=>getPrompt(shot,model,language)),'Subject action: '+text(fields.action)+'.','Ending frame: '+text(fields.end)+'.','Preserve: '+text(fields.retention)+'.']:['主体与环境：'+text(fields.subject)+'。','起幅：'+text(fields.start)+'。','镜头时长：'+duration+'秒。',...chosen.map(shot=>getPrompt(shot,model,language)),'主体动作：'+text(fields.action)+'。','落幅：'+text(fields.end)+'。','保留属性：'+text(fields.retention)+'。']).join('\n');}
function updateComposerOutputs(){const fields=state.composerFields[state.composerLanguage],duration=Math.max(1,Math.min(30,Number(fields.duration)||4)),values=['size','angle','lens','movement'].map(key=>{const shot=byId.get(state.composerSelection[key]);return shot?state.composerLanguage==='en'?en(shot):zh(shot):'—';}),endpoints=text(fields.start)+' → '+text(fields.end),row=[...values,endpoints,duration+(state.composerLanguage==='en'?' seconds':' 秒')];$('shot-description').value=['景别\t角度\t焦距\t运镜\t起幅→落幅\t时长',row.join('\t')].join('\n');$('reader').querySelector('[data-shot-table-row]').innerHTML=row.map(value=>'<td>'+esc(value)+'</td>').join('');$('reader').querySelector('[data-slate-duration]').textContent=duration+' 秒';$('reader').querySelector('[data-slate-tags]').innerHTML=categoryDefs.map(category=>'<span>'+esc(byId.get(state.composerSelection[category.key])?zh(byId.get(state.composerSelection[category.key])):'不额外指定')+'</span>').join('');['seedance','h3'].forEach(model=>{const output=$(model+'-output'),language=state.composerPromptLanguage[model];output.value=composerOutput(model,language);output.lang=language;});}
function setComposerLanguage(language){state.composerLanguage=language;document.querySelectorAll('[data-composer-language]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.composerLanguage===language)));document.querySelectorAll('[data-composer-field]').forEach(input=>input.value=state.composerFields[language][input.dataset.composerField]);updateComposerOutputs();}
