function highlight(value,query){const source=text(value);if(!query)return esc(source);const terms=query.trim().split(/\s+/).filter(Boolean).sort((a,b)=>b.length-a.length).map(term=>term.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'));if(!terms.length)return esc(source);const regex=new RegExp('('+terms.join('|')+')','gi');return source.split(regex).map((part,i)=>i%2?'<mark>'+esc(part)+'</mark>':esc(part)).join('');}
